import{_ as n,y as u,a,o as p,ag as o,D as t,I as s,g as i}from"./chunks/framework.C2qfZH9T.js";const _=JSON.parse('{"title":"Prix du groupe de clients | Tarification par niveau","description":"","frontmatter":{},"headers":[],"relativePath":"customer/customer-group-price.md","filePath":"customer/customer-group-price.md","lastUpdated":1782937842000}'),l={name:"customer/customer-group-price.md"};function d(c,e,g,m,f,x){const r=u("ImagePopup");return p(),a("div",null,[e[0]||(e[0]=o('<h1 id="prix-du-groupe-de-clients-tarification-par-niveau" tabindex="-1">Prix du groupe de clients | Tarification par niveau <a class="header-anchor" href="#prix-du-groupe-de-clients-tarification-par-niveau" aria-label="Permalink to &quot;Prix du groupe de clients | Tarification par niveau&quot;">​</a></h1><p>La tarification par groupe de clients dans ExalandStore permet aux propriétaires de magasins de proposer différents prix de produits à différents groupes de clients, tels que <strong>Général, Grossiste ou Invité</strong>.</p><p>Cette fonctionnalité aide les entreprises à créer des stratégies de tarification personnalisées, à récompenser les acheteurs fidèles et à encourager les achats groupés.</p><p>En affectant les clients à des groupes spécifiques, vous pouvez contrôler combien chaque groupe paie pour le même produit, rendant ainsi votre modèle de tarification plus flexible et axé sur le client.</p><h3 id="etapes-pour-creer-un-prix-de-groupe-de-clients-dans-exalandstore" tabindex="-1">Étapes pour créer un prix de groupe de clients dans ExalandStore <a class="header-anchor" href="#etapes-pour-creer-un-prix-de-groupe-de-clients-dans-exalandstore" aria-label="Permalink to &quot;Étapes pour créer un prix de groupe de clients dans ExalandStore&quot;">​</a></h3><p><strong>Étape 1</strong> : Tout d&#39;abord, créez le groupe de clients et attribuez-le au client, ou utilisez par défaut des groupes tels que <strong>Général, Vente en gros ou Invité</strong>.</p><p><strong>Étape 2</strong> : Connectez-vous au panneau d&#39;administration d&#39;ExalandStore et accédez à <strong>Catalogue &gt;&gt; Produits</strong>.</p><p>Créez un nouveau produit et accédez à la page de modification du produit. Vous pourrez voir la section <strong>Prix du groupe de clients</strong> comme indiqué dans l&#39;image ci-dessous.</p>',8)),t(r,{src:"/images/customer/customerPrice.png",alt:"Customer Group Price"}),e[1]||(e[1]=o(" <p><strong>Étape 3</strong> : Cliquez maintenant sur <strong>Ajouter un nouveau</strong> et ajoutez les champs ci-dessous :</p><ul><li><p><strong>A) Prix réduit</strong> – Définissez un pourcentage de remise sur le prix du produit.</p></li><li><p><strong>B) Prix fixe</strong> – Fixez un prix fixe sur le produit après l&#39;offre.</p></li><li><p><strong>C) Quantité</strong> – Quantité minimale requise pour profiter de l&#39;offre.</p></li><li><p><strong>D) Groupe de clients</strong> – Sélectionnez le groupe de clients (Prime, Invité, Vente en gros, Général, etc.).</p></li></ul><p><em>(Remarque : vous pouvez créer des groupes selon vos besoins.)</em></p><hr><p><strong>Exemple de prix fixe</strong></p><p>Ici, j&#39;ai fixé le prix fixe du produit dans le <strong>groupe Client Invité</strong> avec une quantité minimale de 1.</p><p>Cela signifie que si vous achetez une pièce de ce produit à 2 500 $ et qu&#39;un prix de groupe client est ajouté à 220 $, le coût sera de 220 $ pour une quantité d&#39;un.</p><p>Alors maintenant, cliquez sur le bouton <strong>Enregistrer</strong> comme indiqué ci-dessous.</p>",9)),t(r,{src:"/images/customer/groupPrice.png",alt:"Save Customer Group Price"}),e[2]||(e[2]=s()),e[3]||(e[3]=i("p",null,"Enregistrez maintenant le produit. Vous pouvez voir le prix changer selon le groupe.",-1)),e[4]||(e[4]=i("p",null,"Tel que défini pour le groupe d'invités avec le prix fixe, il affiche le prix en fonction du groupe d'invités, comme indiqué ci-dessous.",-1)),t(r,{src:"/images/customer/priceOutput.png",alt:"Group Price Output"}),e[5]||(e[5]=o(' <h3 id="ajout-de-tarifs-pour-plusieurs-groupes-de-clients" tabindex="-1">Ajout de tarifs pour plusieurs groupes de clients <a class="header-anchor" href="#ajout-de-tarifs-pour-plusieurs-groupes-de-clients" aria-label="Permalink to &quot;Ajout de tarifs pour plusieurs groupes de clients&quot;">​</a></h3><p>Vous pouvez également ajouter plusieurs options de tarification de groupe de clients pour différentes quantités ou groupes afin d&#39;encourager les achats groupés et de proposer de meilleures offres.</p><p>Par exemple, vous pouvez configurer la structure de tarification par niveau suivante :</p><p><strong>Achetez-en 2 pour 400,00 $ chacun et économisez 55,56 %</strong></p><p><strong>Achetez-en 3 pour 350,00 $ chacun et économisez 61,11 %</strong></p><p><strong>Achetez-en 4 pour 200,00 $ chacun et économisez 77,78 %</strong></p><p><strong>Achetez-en 5 pour 150,00 $ chacun et économisez 83,33 %</strong></p><p>Ces niveaux de tarification peuvent être ajoutés directement dans la section Prix du groupe de clients du panneau d&#39;administration, comme indiqué ci-dessous :</p>',9)),t(r,{src:"/images/customer/all-group-price.png",alt:"Multiple Customer Group Pricing"}),e[6]||(e[6]=s()),e[7]||(e[7]=i("p",null,"Vous pouvez consulter la vue Storefront pour voir comment toutes les options de tarification client à plusieurs niveaux apparaissent ensemble pour le même produit.",-1)),t(r,{src:"/images/customer/priceOutput1.png",alt:"Storefront Multiple Customer Group Pricing"})])}const P=n(l,[["render",d]]);export{_ as __pageData,P as default};
